"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8843],{8843:e=>{e.exports=JSON.parse('{"id":"base-s1","slug":"base-s1","trackId":"base","order":15,"title":"20 Services for Working with Crypto","subtitle":"Clear Rules for Protecting Capital","estimatedMinutes":4,"access":"free","quizCount":3,"blueprintCount":0,"trainerIds":["HUB-CALC-08"],"markdown":"Reference \xb7 20 services\\n\\n## Services from the Course\\n\\nWhat they are and where to find them, on one page\\n\\nEverything mentioned in the lessons is collected here: what each service does and where to learn more. Open services through these links or your own bookmarks, rather than search results and advertisements: fake websites are common.\\n\\n### Wallets\\n\\n- OKX Wallet ↗ (opens in a new tab) web3.okx.com\\n \\nA wallet where you hold the keys, rather than an exchange. A browser extension and app, installed in Guide 1.\\n\\n- MetaMask ↗ (opens in a new tab) metamask.io\\n \\nThe best-known wallet for Ethereum and similar networks. Also non-custodial. Lesson 8.\\n\\n- Ledger ↗ (opens in a new tab) ledger.com\\n \\nA hardware “cold” wallet: keys remain on a separate device rather than your computer. Lesson 3.\\n\\n- Trezor ↗ (opens in a new tab) trezor.io\\n \\nAnother hardware wallet and a longstanding Ledger competitor. Lesson 3.\\n\\n- Safe ↗ (opens in a new tab) safe.global\\n \\nA multisignature wallet: a transfer requires multiple keys, such as 2 of 2 or 2 of 3. Lesson 3.\\n\\n### Check Transfers and Wallets\\n\\nDo not connect anything or sign anything: these tools are for viewing only.\\n\\n- DeBank ↗ (opens in a new tab) debank.com\\n \\nView an entire wallet by address: coins across networks and DeFi positions. Lesson 4.\\n\\n- Etherscan ↗ (opens in a new tab) etherscan.io\\n \\nEthereum block explorer: enter an address or transaction identifier to check whether funds arrived. Lesson 4.\\n\\n- Tronscan ↗ (opens in a new tab) tronscan.org\\n \\nThe equivalent explorer for the Tron network. Lesson 4.\\n\\n- Solscan ↗ (opens in a new tab) solscan.io\\n \\nThe equivalent explorer for Solana. Lesson 4.\\n\\n- Revoke.cash ↗ (opens in a new tab) revoke.cash\\n \\nShows which websites have permission to spend your tokens (Approve), and lets you revoke those permissions. Lesson 6.\\n\\n### DeFi\\n\\n- Aave ↗ (opens in a new tab) aave.com\\n \\nLoans secured by crypto collateral. One of the two largest lending services. Lesson 7.\\n\\n- Morpho ↗ (opens in a new tab) morpho.org\\n \\nThe other major lending service discussed in the loans lesson. Lesson 7.\\n\\n- Uniswap ↗ (opens in a new tab) uniswap.org\\n \\nA decentralized exchange: swap tokens directly from your wallet without registration. A swap cannot be reversed. Lesson 6.\\n\\n- Jupiter ↗ (opens in a new tab) jup.ag\\n \\nToken swaps on Solana, finding the best rate across multiple venues. Lesson 6.\\n\\n- DeFiLlama ↗ (opens in a new tab) defillama.com\\n \\nDeFi statistics: funds held in each protocol (TVL) and available yields. Lesson 7.\\n\\n- Chainlink ↗ (opens in a new tab) chain.link\\n \\nOracles bring external prices into smart contracts. You need not visit it, but loans and liquidations depend on this infrastructure. Lesson 6.\\n\\n### Stablecoins\\n\\n- Tether ↗ (opens in a new tab) tether.to\\n \\nIssues USDT. Its website provides reserve reports. Lesson 5.\\n\\n- Circle ↗ (opens in a new tab) circle.com\\n \\nIssues USDC. Its website also provides reserve reports. Lesson 5.\\n\\n- Sky ↗ (opens in a new tab) sky.money\\n \\nThe protocol behind DAI, formerly called MakerDAO. Lesson 5.\\n\\n### Source of Funds\\n\\n- Chainalysis ↗ (opens in a new tab) chainalysis.com\\n \\nTraces illicit cryptocurrency; exchanges use its checks. You do not need to use it yourself, but it explains AML checks. Lesson 9.\\n\\nExchanges and currency-conversion services are deliberately absent: cryptocurrency advertising is prohibited in Russia, and some venues are under sanctions. Lesson 9 explains how to choose where to buy. This is neither advertising nor advice on investments, but a map of the services discussed. ← Guide 1 OKX Wallet\\n\\n---\\n\\n\\n---","blueprints":[],"quiz":[{"id":"q-base-s1-1","prompt":"Which service in the directory is used to set up a multisignature wallet (2/2 or 2/3)?","options":[{"id":"base-s1-1-1","label":"Safe (safe.global)","isCorrect":true,"feedback":"Correct. Safe (safe.global)"},{"id":"base-s1-1-2","label":"Lido (lido.fi)","isCorrect":false,"feedback":"Incorrect. Safe (safe.global)"},{"id":"base-s1-1-3","label":"Tether (tether.to)","isCorrect":false,"feedback":"Incorrect. Safe (safe.global)"}],"explanation":"Safe (safe.global)","sourceRef":"CAPITAL_BASE:2884–2887"},{"id":"q-base-s1-2","prompt":"Which blockchain explorers in the directory correspond to Ethereum, Tron and Solana?","options":[{"id":"base-s1-2-1","label":"etherscan.io, tronscan.org and solscan.io","isCorrect":true,"feedback":"Correct. etherscan.io, tronscan.org and solscan.io"},{"id":"base-s1-2-2","label":"Only coinmarketcap.com for every transfer","isCorrect":false,"feedback":"Incorrect. etherscan.io, tronscan.org and solscan.io"},{"id":"base-s1-2-3","label":"Only the bank’s online account","isCorrect":false,"feedback":"Incorrect. etherscan.io, tronscan.org and solscan.io"}],"explanation":"etherscan.io, tronscan.org and solscan.io","sourceRef":"CAPITAL_BASE:2892–2906"},{"id":"q-base-s1-3","prompt":"According to the directory, what role does Chainlink (chain.link) play in DeFi infrastructure?","options":[{"id":"base-s1-3-1","label":"It issues the USDT stablecoin","isCorrect":false,"feedback":"Incorrect. It provides a network of oracles delivering external market prices to lending and liquidation smart contracts"},{"id":"base-s1-3-2","label":"It provides a network of oracles delivering external market prices to lending and liquidation smart contracts","isCorrect":true,"feedback":"Correct. It provides a network of oracles delivering external market prices to lending and liquidation smart contracts"},{"id":"base-s1-3-3","label":"It stores users’ seed phrases","isCorrect":false,"feedback":"Incorrect. It provides a network of oracles delivering external market prices to lending and liquidation smart contracts"}],"explanation":"It provides a network of oracles delivering external market prices to lending and liquidation smart contracts","sourceRef":"CAPITAL_BASE:2923–2926"}],"source":{"file":"00_FREE_GIFT_MakeCash_Crypto_And_Capital_Base_15_Lessons.md","sha256":"88a3efb162434bb8a9b3b000caee579d9c27005a8ea46ddf4ef9cafb50dc45cc","lineStart":2858,"lineEnd":2991}}')}}]);